using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;
public class ProductionMeshFactory {
 public readonly List<Vector3> vertices=new List<Vector3>();public readonly List<Vector2> uv=new List<Vector2>();public readonly List<int>[] indices={new List<int>(),new List<int>(),new List<int>()};
 public void Tri(Vector3 a,Vector3 b,Vector3 c,int material=0){if(Vector3.Cross(b-a,c-a).sqrMagnitude<1e-12f)return;int n=vertices.Count;var normal=Vector3.Cross(b-a,c-a).normalized;foreach(var v in new[]{a,b,c}){vertices.Add(v);uv.Add(Mathf.Abs(normal.y)>.7f?new Vector2(v.x,v.z):Mathf.Abs(normal.x)>.7f?new Vector2(v.z,v.y):new Vector2(v.x,v.y));}indices[material].AddRange(new[]{n,n+1,n+2});}
 public void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d,int m=0){Tri(a,b,c,m);Tri(a,c,d,m);}
 public void Beam(Vector3 a,Vector3 b,float radius,int material=0,int sides=6){if(Vector3.Distance(a,b)<.00001f)return;var direction=(b-a).normalized;var u=Vector3.Cross(direction,Mathf.Abs(direction.y)<.9f?Vector3.up:Vector3.right).normalized;var v=Vector3.Cross(direction,u);for(int i=0;i<sides;i++){float q=i*2*Mathf.PI/sides,r=(i+1)*2*Mathf.PI/sides;var p=u*Mathf.Cos(q)+v*Mathf.Sin(q);var s=u*Mathf.Cos(r)+v*Mathf.Sin(r);Quad(a+p*radius,a+s*radius,b+s*radius,b+p*radius,material);Tri(a,a+s*radius,a+p*radius,material);Tri(b,b+p*radius,b+s*radius,material);}}
 public Mesh Finish(string name){var mesh=new Mesh{name=name,indexFormat=vertices.Count>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.subMeshCount=indices.Count(x=>x.Count>0);int count=0;foreach(var sub in indices)if(sub.Count>0)mesh.SetTriangles(sub,count++);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();return mesh;}
 public static Mesh Dome(out Mesh seams){var t=(1+Mathf.Sqrt(5))/2;var points=new[]{new Vector3(-1,t,0),new Vector3(1,t,0),new Vector3(-1,-t,0),new Vector3(1,-t,0),new Vector3(0,-1,t),new Vector3(0,1,t),new Vector3(0,-1,-t),new Vector3(0,1,-t),new Vector3(t,0,-1),new Vector3(t,0,1),new Vector3(-t,0,-1),new Vector3(-t,0,1)}.Select(v=>v.normalized).ToArray();int[] faces={0,11,5,0,5,1,0,1,7,0,7,10,0,10,11,1,5,9,5,11,4,11,10,2,10,7,6,7,1,8,3,9,4,3,4,2,3,2,6,3,6,8,3,8,9,4,9,5,2,4,11,6,2,10,8,6,7,9,8,1};var tris=new List<Vector3[]>();for(int i=0;i<faces.Length;i+=3)tris.Add(new[]{points[faces[i]],points[faces[i+1]],points[faces[i+2]]});for(int level=0;level<2;level++){var more=new List<Vector3[]>();foreach(var f in tris){var a=(f[0]+f[1]).normalized;var b=(f[1]+f[2]).normalized;var c=(f[2]+f[0]).normalized;more.AddRange(new[]{new[]{f[0],a,c},new[]{a,f[1],b},new[]{c,b,f[2]},new[]{a,b,c}});}tris=more;}
 var panels=new ProductionMeshFactory();var frame=new ProductionMeshFactory();foreach(var tri in tris){var poly=new List<Vector3>();for(int i=0;i<3;i++){var a=tri[i];var b=tri[(i+1)%3];if(a.y>=-.0001f)poly.Add(new Vector3(a.x,Mathf.Max(0,a.y),a.z));if((a.y>=0)!=(b.y>=0))poly.Add(Vector3.Lerp(a,b,-a.y/(b.y-a.y)));}for(int k=poly.Count-1;k>=0&&poly.Count>1;k--)if(Vector3.Distance(poly[k],poly[(k+1)%poly.Count])<.00001f)poly.RemoveAt(k);if(poly.Count<3)continue;var center=poly.Aggregate(Vector3.zero,(sum,p)=>sum+p)/poly.Count;bool window=center.z<-.5f&&center.y>.22f&&center.y<.65f&&Mathf.Abs(center.x)>.25f;int material=window?1:0;for(int i=1;i<poly.Count-1;i++)panels.Tri(Vector3.Lerp(center,poly[0],.984f),Vector3.Lerp(center,poly[i],.984f),Vector3.Lerp(center,poly[i+1],.984f),material);for(int i=0;i<poly.Count;i++)frame.Beam(poly[i]*.997f,poly[(i+1)%poly.Count]*.997f,.0028f,0,4);}
 seams=frame.Finish("Geodesic pressure-shell frame");return panels.Finish("Original clipped icosahedral panels");}
 public static Mesh Beveled(bool cabin=false){var mesh=new ProductionMeshFactory();Vector2[] p=cabin?new[]{new Vector2(-.5f,-.5f),new Vector2(.5f,-.5f),new Vector2(.5f,.08f),new Vector2(.28f,.5f),new Vector2(-.4f,.5f),new Vector2(-.5f,.3f)}:new[]{new Vector2(-.5f,-.5f),new Vector2(.5f,-.5f),new Vector2(.5f,.32f),new Vector2(.32f,.5f),new Vector2(-.32f,.5f),new Vector2(-.5f,.32f)};for(int i=0;i<p.Length;i++){int j=(i+1)%p.Length;var a=new Vector3(-.5f,p[i].y,p[i].x);var b=new Vector3(-.5f,p[j].y,p[j].x);var c=new Vector3(.5f,p[j].y,p[j].x);var d=new Vector3(.5f,p[i].y,p[i].x);mesh.Quad(a,b,c,d,cabin&&i==2?1:0);mesh.Tri(new Vector3(-.5f,0,0),b,a);mesh.Tri(new Vector3(.5f,0,0),d,c);}foreach(var index in mesh.indices)for(int i=0;i<index.Count;i+=3){int swap=index[i+1];index[i+1]=index[i+2];index[i+2]=swap;}return mesh.Finish(cabin?"Sloped crew-cab enclosure":"Chamfered modular enclosure");}
 public static Mesh Wheel(int segments,int treads){var m=new ProductionMeshFactory();var profile=new[]{new Vector2(.36f,-1),new Vector2(.5f,-.85f),new Vector2(.5f,.85f),new Vector2(.36f,1)};for(int k=0;k<profile.Length-1;k++)for(int i=0;i<segments;i++){float a=i*Mathf.PI*2/segments,b=(i+1)*Mathf.PI*2/segments;Func<float,Vector2,Vector3> v=(angle,p)=>new Vector3(Mathf.Cos(angle)*p.x,p.y,Mathf.Sin(angle)*p.x);m.Quad(v(a,profile[k]),v(a,profile[k+1]),v(b,profile[k+1]),v(b,profile[k]));}for(int side=-1;side<=1;side+=2){for(int i=0;i<segments;i++){float a=i*2*Mathf.PI/segments,b=(i+1)*2*Mathf.PI/segments;var p=new Vector3(Mathf.Cos(a)*.36f,side*1.01f,Mathf.Sin(a)*.36f);var q=new Vector3(Mathf.Cos(b)*.36f,side*1.01f,Mathf.Sin(b)*.36f);if(side==1)m.Tri(new Vector3(0,side*1.01f,0),q,p,1);else m.Tri(new Vector3(0,side*1.01f,0),p,q,1);}for(int bolt=0;bolt<6;bolt++){float a=bolt*Mathf.PI/3;var c=new Vector3(Mathf.Cos(a)*.24f,side*1.025f,Mathf.Sin(a)*.24f);m.Beam(c,c+Vector3.up*side*.08f,.026f,1,4);}}for(int i=0;i<treads;i++){float a=i*Mathf.PI*2/treads;var center=new Vector3(Mathf.Cos(a)*.5f,0,Mathf.Sin(a)*.5f);m.Beam(center-Vector3.up*.8f,center+Vector3.up*.8f,.02f,0,4);}return m.Finish("Six-wheel tire/rim LOD "+segments);}
}
